@app.get('/kutuphane/ara/{kitap_adi}')
async def internetten_ara(kitap_adi: str):
    url = f'https://openlibrary.org/search.json?q={kitap_adi}&limit=2'

    async with httpx.AsyncClient() as client:
        yanit = await client.get(url)
        data = yanit.json()

        kitaplar = []
        for doc in data.get('docs', []):
            kitaplar.append({
                'baslik': doc.get('title'),
                'yazar': doc.get('author_name', ['Bilinmiyor'])[0]
            })
        return {'arama': kitap_adi, 'sonuclar': kitaplar}

Dış servisler çökebilir veya internet kopabilir. Sistemimizin kilitlenmemesi için Timeout ve try-except koymalıyız:

try:
    async with httpx.AsyncClient(timeout=3.0) as client:
        res = await client.get(url)
        res.raise_for_status()  # 4xx veya 5xx hatası varsa fırlatır
except httpx.TimeoutException:
    raise HTTPException(status_code=504, detail='Dış API zaman aşımına uğradı!')
except httpx.RequestError:
    raise HTTPException(status_code=503, detail='Dış API servisine ulaşılamıyor!')

@app.get('/gunun-tavsiyesi')
async def tavsiye_al():
    url = 'https://api.adviceslip.com/advice'
    async with httpx.AsyncClient() as client:
        res = await client.get(url)
        # Gelen JSON: {'slip': {'id': 1, 'advice': '...'}}
        return {'tavsiye': res.json()['slip']['advice']}

